package market

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"regexp"
	"slices"
	"strings"
)

// listed.json is generated by cmd/genlisted from the screener's constituent
// lists and Yahoo measurements (rule and exclusions in the contract): the
// Asian index constituents no named instrument trades already, each a quote
// feed under its own Yahoo ticker, and the constituents left research-only
// with why.
//
//go:embed listed.json
var listedJSON []byte

// ListedPattern is a listed instrument's symbol: its upper-case Yahoo ticker
// on one of the venues the screener's Asian lists trade on (6501.T,
// 000810.KS, 0005.HK, 1216.TW, C38U.SI, BBNI.JK, KBANK.BK, 1066.KL, VNM.VN),
// or Taipei Exchange (TPEx, .TWO: 6488.TWO), which keeps TWSE's session.
const ListedPattern = `^[0-9A-Z]{1,6}\.(T|KS|HK|TW|TWO|SI|JK|BK|KL|VN)$`

var listedTicker = regexp.MustCompile(ListedPattern)

// listedVenues are each venue's quote currencies (SGX lists some lines in USD).
var listedVenues = map[string][]string{TSE: {"JPY"}, KRX: {"KRW"}, HKEX: {"HKD"}, TWSE: {"TWD"}, SGX: {"SGD", "USD"},
	IDX: {"IDR"}, SET: {"THB"}, BURSA: {"MYR"}, HOSE: {"VND"}}

// Listed are the listed instruments, in listed.json's order: quote feeds
// (venue "yahoo", Class Stock, region "asia") whose Symbol and Pair are the
// Yahoo ticker. They are not in Universe, so nothing that enumerates the
// named universe into a prompt, a tool enum or a batch job sees them; Lookup,
// Instruments, the quote-feed poller and the assets list do.
var Listed, listedBy, listedIndex, listedExcluded = mustLoadListed(listedJSON, slices.Concat(Universe, QuoteFeeds))

// IsListed reports whether a is a listed instrument (a set lookup: AssetInfo
// keeps its positional fields).
func (a AssetInfo) IsListed() bool {
	i, ok := listedBy[a.Symbol]
	return ok && Listed[i].Pair == a.Pair
}

// IsListed reports whether the row is a listed instrument's.
func (a Asset) IsListed() bool {
	i, ok := listedBy[a.Symbol]
	return ok && Listed[i].Pair == a.Pair
}

// ListedExcluded is why a screener constituent's ticker is not listed
// ("Trades under $1M a day (30-day mean $127k on 2026-10-13)"); ok is false
// for a ticker the generator did not exclude.
func ListedExcluded(ticker string) (reason string, ok bool) {
	reason, ok = listedExcluded[strings.ToUpper(strings.TrimSpace(ticker))]
	return reason, ok
}

// Instruments is every instrument, the named Universe then Listed, as a new
// slice.
func Instruments() []AssetInfo { return slices.Concat(Universe, Listed) }

// ByYahoo is the instrument whose listing is ticker on Yahoo: the first named
// one in Universe order, else the listed row of that ticker.
func ByYahoo(ticker string) (AssetInfo, bool) {
	t := strings.ToUpper(strings.TrimSpace(ticker))
	if t == "" {
		return AssetInfo{}, false
	}
	for _, a := range Universe {
		if a.Listing != nil && strings.EqualFold(a.Listing.Yahoo, t) {
			return a, true
		}
	}
	if i, ok := listedBy[t]; ok {
		return Listed[i], true
	}
	return AssetInfo{}, false
}

// lookupListed is the listed row of an upper-case symbol.
func lookupListed(symbol string) (AssetInfo, bool) {
	if i, ok := listedBy[symbol]; ok {
		return Listed[i], true
	}
	return AssetInfo{}, false
}

// listedRow is the part of a listed.json row the loader reads.
type listedRow struct {
	Symbol, Name, Market, Venue, Currency, Underlying, Index, Left string
}

func mustLoadListed(raw []byte, named []AssetInfo) ([]AssetInfo, map[string]int, []string, map[string]string) {
	rows, by, index, excluded, err := loadListed(raw, named)
	if err != nil {
		panic(err)
	}
	return rows, by, index, excluded
}

// ListedIndex is the index a listed symbol belongs to ("Nikkei 225"; "" once
// it left every list); ok is false for any other symbol.
func ListedIndex(symbol string) (index string, ok bool) {
	i, ok := listedBy[strings.ToUpper(strings.TrimSpace(symbol))]
	if !ok {
		return "", false
	}
	return listedIndex[i], true
}

// loadListed parses listed.json strictly: a bad ticker, a duplicate, a
// collision with a named symbol or Yahoo listing, an unknown venue or
// currency, or an underlying line over 120 characters fails it. index is
// each row's index name, in row order.
func loadListed(raw []byte, named []AssetInfo) (rows []AssetInfo, by map[string]int, index []string, excluded map[string]string, err error) {
	var f struct {
		Rows     []listedRow `json:"rows"`
		Excluded []struct {
			Ticker, Reason string
		} `json:"excluded"`
	}
	if err := json.Unmarshal(raw, &f); err != nil {
		return nil, nil, nil, nil, fmt.Errorf("market: listed.json: %w", err)
	}
	taken := map[string]bool{}
	for _, a := range named {
		taken[strings.ToUpper(a.Symbol)] = true
		if a.Listing != nil && a.Listing.Yahoo != "" {
			taken[strings.ToUpper(a.Listing.Yahoo)] = true
		}
	}
	out := make([]AssetInfo, 0, len(f.Rows))
	by = make(map[string]int, len(f.Rows))
	for i, r := range f.Rows {
		ccys, venue := listedVenues[r.Venue]
		_, dup := by[r.Symbol]
		switch {
		case !listedTicker.MatchString(r.Symbol):
			return nil, nil, nil, nil, fmt.Errorf("market: listed row %d: %q is not a listed ticker", i, r.Symbol)
		case dup:
			return nil, nil, nil, nil, fmt.Errorf("market: listed row %s twice", r.Symbol)
		case taken[r.Symbol]:
			return nil, nil, nil, nil, fmt.Errorf("market: listed row %s collides with a named instrument", r.Symbol)
		case !venue:
			return nil, nil, nil, nil, fmt.Errorf("market: listed row %s: unknown venue %q", r.Symbol, r.Venue)
		case !slices.Contains(ccys, r.Currency):
			return nil, nil, nil, nil, fmt.Errorf("market: listed row %s: currency %q on %s", r.Symbol, r.Currency, r.Venue)
		case strings.TrimSpace(r.Name) == "" || r.Underlying == "" || len(r.Underlying) > 120:
			return nil, nil, nil, nil, fmt.Errorf("market: listed row %s: name or underlying", r.Symbol)
		case r.Currency != "USD" && !strings.HasSuffix(r.Underlying, r.Currency+"→USD at Yahoo FX"):
			return nil, nil, nil, nil, fmt.Errorf("market: listed row %s: underlying %q states no FX", r.Symbol, r.Underlying)
		}
		by[r.Symbol] = len(out)
		index = append(index, r.Index)
		out = append(out, AssetInfo{Symbol: r.Symbol, Pair: r.Symbol, Name: r.Name, Class: Stock, Venue: QuoteFeedVenue,
			Listing: &Listing{Region: "asia", SessionVenue: r.Venue, Underlying: r.Underlying, LocalCurrency: r.Currency, Yahoo: r.Symbol}})
	}
	excluded = make(map[string]string, len(f.Excluded))
	for _, x := range f.Excluded {
		if _, dup := by[x.Ticker]; dup || x.Reason == "" {
			return nil, nil, nil, nil, fmt.Errorf("market: listed.json excludes %q with no reason, or lists it too", x.Ticker)
		}
		excluded[strings.ToUpper(x.Ticker)] = x.Reason
	}
	return out, by, index, excluded, nil
}
